// Общие шаги для меню «More» на телефоне (#e9cbda). Admin, компания «test». Только просмотр: пункты меню НЕ нажимаются
// (GPS Workflow при первом открытии покупает номер Twilio — context.md / research/0c3606.md).
// Не сверено с сайтом при записи (сайт не открывался — правило L-20261007-1): разметка панели (role=dialog / aside / nav),
// имя кнопки «More» в HE (aria-label может быть переведён), HE-подпись пункта GPS Workflow (берём /GPS/),
// пункты — ссылки или кнопки. HE-подписи остальных пунктов — по скриншоту 1748ba2b-v-more-390x844-he.png (14.10).
import { expect, Locator, Page } from '@playwright/test';
import { ADMIN_STATE, Lang, TEST_COMPANY_ID, prepare } from '../dispatch-sms/dispatch-helpers';

export { ADMIN_STATE, TEST_COMPANY_ID };
export type { Lang };

/** Размеры телефона из тикета (проверено программистом): 375×812 — iPhone (WebKit), 390×844 — Chrome (Android-прогон). */
export const PHONES = [
  { label: '375x812', viewport: { width: 375, height: 812 }, tag: '@iphone' },
  { label: '390x844', viewport: { width: 390, height: 844 }, tag: '@android' },
] as const;

/** 16 пунктов admin в порядке десктопа (context.md, #2c26e8; GPS Workflow — #0c3606, сразу под AI). */
export const ITEMS: Record<Lang, (string | RegExp)[]> = {
  en: [
    'Home', 'AI', /^GPS Workflow$/, 'Schedule', 'Leads', 'Jobs', 'Clients', 'Estimates', 'Invoices',
    'Price Book', 'Inventory', 'Reports', 'Payments', 'Map', 'Admin Panel', 'Support Console',
  ],
  he: [
    'בית', 'AI', /GPS/, 'לוח זמנים', 'לידים', 'עבודות', 'לקוחות', 'הערכות מחיר', 'חשבוניות',
    'ספר מחירים', 'מלאי', 'דוחות', 'תשלומים', 'מפה', 'פאנל ניהול', 'ממשק תמיכה',
  ],
};

const OPEN_NAV = /Open navigation|^More$|^עוד$|ניווט/;

/** Пункт меню внутри панели: ссылка или кнопка с точным именем. */
export function menuItem(panel: Locator, name: string | RegExp): Locator {
  const opts = typeof name === 'string' ? { name, exact: true } : { name };
  return panel.getByRole('link', opts).or(panel.getByRole('button', opts)).first();
}

/**
 * /dashboard (язык, компания «test») → «More» в нижней панели → панель меню со всеми 16 пунктами.
 * Панель — видимый контейнер (dialog / aside / nav), в котором есть и первый, и последний пункт; берём самый вложенный.
 */
export async function openMoreMenu(page: Page, lang: Lang): Promise<{ panel: Locator; items: Locator[] }> {
  await prepare(page, lang);
  await page.goto('/dashboard');
  const more = page.getByRole('button', { name: OPEN_NAV }).filter({ visible: true }).first();
  await expect(more, 'кнопка «More» в нижней панели').toBeVisible({ timeout: 30_000 });
  await more.click();

  const names = ITEMS[lang];
  const first = names[0] as string;
  const last = names[names.length - 1] as string;
  const panel = page
    .locator('[role="dialog"], aside, nav')
    .filter({ visible: true })
    .filter({ hasText: first })
    .filter({ hasText: last })
    .last();
  await expect(panel, 'панель меню открыта').toBeVisible();

  // AI и Inventory подгружаются через несколько секунд — ждём каждый пункт.
  const items = names.map((n) => menuItem(panel, n));
  for (let i = 0; i < items.length; i++) {
    await expect(items[i], `пункт меню «${names[i]}»`).toBeVisible({ timeout: 20_000 });
  }
  // Пока всё догружается, раскладка может сдвинуться — ждём, пока последний пункт перестанет двигаться.
  await expect.poll(async () => {
    const a = await items[items.length - 1].boundingBox();
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
    const b = await items[items.length - 1].boundingBox();
    return a && b ? Math.abs(a.y - b.y) + Math.abs(a.x - b.x) : 999;
  }, { message: 'раскладка меню устоялась' }).toBeLessThan(0.5);
  return { panel, items };
}

export type Box = { x: number; y: number; width: number; height: number };

export async function boxes(items: Locator[]): Promise<Box[]> {
  const out: Box[] = [];
  for (const it of items) {
    const b = await it.boundingBox();
    expect(b, 'у пункта есть размеры').not.toBeNull();
    out.push(b!);
  }
  return out;
}

const fmt = (bs: Box[]) => bs.map((b) => `[x${Math.round(b.x)} y${Math.round(b.y)} w${Math.round(b.width)}]`).join(' ');

/** Одна колонка: левый край и ширина у всех пунктов совпадают (±2px). */
export function expectSingleColumn(bs: Box[]) {
  const x0 = bs[0].x;
  const w0 = bs[0].width;
  for (let i = 1; i < bs.length; i++) {
    expect(Math.abs(bs[i].x - x0), `пункт ${i + 1}: тот же левый край, что у первого (одна колонка) ${fmt(bs)}`).toBeLessThanOrEqual(2);
    expect(Math.abs(bs[i].width - w0), `пункт ${i + 1}: та же ширина, что у первого (одна колонка) ${fmt(bs)}`).toBeLessThanOrEqual(2);
  }
}

/** Порядок сверху вниз: каждый пункт начинается не выше низа предыдущего (без наложения). */
export function expectVerticalOrder(bs: Box[]) {
  for (let i = 1; i < bs.length; i++) {
    expect(bs[i].y, `пункт ${i + 1} ниже пункта ${i} ${fmt(bs)}`).toBeGreaterThanOrEqual(bs[i - 1].y + bs[i - 1].height - 1);
  }
}

/**
 * Нет вертикальной прокрутки: у панели и у каждого предка первого пункта (до body, не включая — страница за меню не в счёт)
 * с overflow-y auto/scroll — scrollHeight ≤ clientHeight (+1px на округление). Возвращает найденные нарушения.
 */
export async function scrollOverflows(panel: Locator, firstItem: Locator) {
  const panelHandle = await panel.elementHandle();
  return firstItem.evaluate((el, root) => {
    const bad: string[] = [];
    let node: HTMLElement | null = el.parentElement;
    while (node && node !== document.body && node !== document.documentElement) {
      const oy = getComputedStyle(node).overflowY;
      const scrollable = oy === 'auto' || oy === 'scroll';
      if ((scrollable || node === root) && node.scrollHeight > node.clientHeight + 1) {
        bad.push(`<${node.tagName.toLowerCase()} class="${node.className}"> scrollHeight ${node.scrollHeight} > clientHeight ${node.clientHeight} (overflow-y ${oy})`);
      }
      node = node.parentElement;
    }
    return bad;
  }, panelHandle);
}

/** В finally: selected-company-id = test (если страница жива). */
export async function restoreCompany(page: Page) {
  if (page.isClosed()) return;
  await page.evaluate((id) => window.localStorage.setItem('selected-company-id', id), TEST_COMPANY_ID).catch(() => undefined);
}
